import{_ as a,o as t,c as i,a0 as o}from"./chunks/framework.DB31oXgM.js";const u=JSON.parse('{"title":"ADR 007: Serialization and Wire Protocol Encoding Format","description":"","frontmatter":{},"headers":[],"relativePath":"adr/007-serialization-wire-format.md","filePath":"adr/007-serialization-wire-format.md"}'),n={name:"adr/007-serialization-wire-format.md"};function r(s,e,c,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-007-serialization-and-wire-protocol-encoding-format" tabindex="-1">ADR 007: Serialization and Wire Protocol Encoding Format <a class="header-anchor" href="#adr-007-serialization-and-wire-protocol-encoding-format" aria-label="Permalink to &quot;ADR 007: Serialization and Wire Protocol Encoding Format&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Standard JSON or bloated protobuf serialization introduces significant packet overhead and CPU parsing latency on 60 Hz realtime UDP connections. To fit within standard MTUs (&lt; 1200 bytes) without packet fragmentation and minimize deserialization overhead, a tight binary wire format is essential.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Realtime Datagrams</strong>: Compact custom big-endian / network-byte-order binary encoding with explicit packet headers: <ul><li><code>Magic</code>: 2 bytes (<code>0x5242</code> / &#39;RB&#39;)</li><li><code>Version</code>: 1 byte (<code>0x01</code>)</li><li><code>MsgType</code>: 1 byte (Handshake, InputFrame, Checksum, Snapshot, etc.)</li><li><code>Payload</code>: Explicit length-bounded, zero-copy parseable byte slice with bounds checking.</li></ul></li><li><strong>Deterministic Checksum</strong>: Blake3 / FNV-1a 32-bit state hashes computed over canonical byte layout.</li><li><strong>Control &amp; Admin API</strong>: JSON over HTTP/REST and WebSockets for session creation, admin moderation, and telemetry queries.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Input datagrams are under 40 bytes per packet including redundant historical inputs.</li><li>Microsecond decode latency on the hot path.</li><li>Malformed datagrams are rejected immediately without CPU exhaustion or memory allocations.</li></ul>',9)])])}const p=a(n,[["render",r]]);export{u as __pageData,p as default};
